8. namespace LegacyTradeReconciliation
9. {
10.     public sealed class RunLedgerStore
11.     {
12.         private readonly string _ledgerPath;
13. 
14.         public RunLedgerStore(string ledgerPath)
15.         {
16.             _ledgerPath = ledgerPath;
17.         }
18. 
19.         public bool Exists(DateTime businessDate, string signature)
20.         {
21.             return LoadEntries().Any(entry =>
22.                 entry.BusinessDate == businessDate &&
23.                 string.Equals(entry.InputSignature, signature, StringComparison.Ordinal));
24.         }
25. 
26.         public void AppendIfMissing(RunLedgerEntry entry)
27.         {
28.             if (Exists(entry.BusinessDate, entry.InputSignature))
29.             {
30.                 return;
31.             }
32. 
33.             bool fileExists = File.Exists(_ledgerPath);
34.             using (var writer = new StreamWriter(_ledgerPath, true))
35.             {
36.                 if (!fileExists)
37.                 {
38.                     writer.WriteLine("business_date,input_signature,total_trades_read,open_break_count,matched_count");
39.                 }
40. 
41.                 writer.WriteLine(string.Join(",",
42.                     entry.BusinessDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
43.                     entry.InputSignature,
44.                     entry.TotalTradesRead.ToString(CultureInfo.InvariantCulture),
45.                     entry.OpenBreakCount.ToString(CultureInfo.InvariantCulture),
46.                     entry.MatchedCount.ToString(CultureInfo.InvariantCulture)));
47.             }
48.         }
49. 
50.         private List<RunLedgerEntry> LoadEntries()
51.         {
52.             if (!File.Exists(_ledgerPath))
53.             {
54.                 return new List<RunLedgerEntry>();
