1. using System.Globalization;
2. using TradeReconciliation.Application;
3. using TradeReconciliation.Domain;
4. using TradeReconciliation.Infrastructure;
5. using TradeReconciliation.Infrastructure.Csv;
6. 
7. namespace TradeReconciliation.Cli;
8. 
9. /// <summary>
10. /// Composition root and console shell. Keeping this separate from <see cref="Program"/> lets the
11. /// whole command-line surface, including exit codes and console text, be exercised by tests.
12. /// </summary>
13. public static class BatchHost
14. {
15.     private static readonly string[] HelpSwitches = ["-h", "--help", "-?", "/?", "/h"];
16. 
17.     public static int Run(string[]? args, TextWriter standardOutput, TextWriter standardError)
18.     {
19.         ArgumentNullException.ThrowIfNull(standardOutput);
20.         ArgumentNullException.ThrowIfNull(standardError);
21. 
22.         if (args is { Length: 1 } && HelpSwitches.Contains(args[0], StringComparer.OrdinalIgnoreCase))
23.         {
24.             standardOutput.WriteLine(RunRequest.Usage);
25.             return ExitCodes.Success;
26.         }
27. 
28.         try
29.         {
30.             RunRequest request = RunRequest.Resolve(args);
31.             BatchOutcome outcome = CreateBatch().Run(request);
32.             standardOutput.WriteLine(DescribeOutcome(outcome));
33.             return ExitCodes.Success;
34.         }
35.         catch (CommandLineException exception)
36.         {
37.             standardError.WriteLine(exception.Message);
38.             standardError.WriteLine(RunRequest.Usage);
39.             return ExitCodes.UsageError;
40.         }
41.         catch (ReconciliationInputException exception)
42.         {
43.             standardError.WriteLine(exception.Message);
44.             return ExitCodes.InputError;
45.         }
46.         catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
47.         {
48.             standardError.WriteLine("Batch input/output failed: " + exception.Message);
49.             return ExitCodes.InputError;
50.         }
51.     }
52. 
53.     /// <summary>Builds the batch from its production collaborators.</summary>
54.     public static ReconciliationBatch CreateBatch()
55.     {
56.         CsvFileGateway gateway = new();
57.         return new ReconciliationBatch(
58.             gateway,
59.             gateway,
60.             new MatchingEngine(),
61.             new EndOfDayReportBuilder(),
62.             new InputSignatureCalculator(),
63.             new RunLedgerStoreFactory());
64.     }
65. 
66.     /// <summary>
67.     /// Produces the operator-facing completion line. The wording is part of the observable
68.     /// behaviour Trade Operations scrapes from batch logs.
69.     /// </summary>
70.     internal static string DescribeOutcome(BatchOutcome outcome)
71.     {
72.         ArgumentNullException.ThrowIfNull(outcome);
73. 
74.         if (outcome.Completion == BatchCompletion.IdempotentRerun)
75.         {
76.             return "Exact rerun detected for " +
77.                    outcome.BusinessDate.ToString(RunRequest.DateFormat, CultureInfo.InvariantCulture) +
78.                    ". Existing outputs were retained.";
79.         }
80. 
81.         ReconciliationResult result = outcome.Result
82.             ?? throw new InvalidOperationException("A processed batch outcome must carry a reconciliation result.");
83. 
84.         return string.Format(
85.             CultureInfo.InvariantCulture,
86.             "Processed {0} trades into {1} matched rows and {2} open breaks.",
87.             result.TotalTradesRead,
88.             result.MatchedTrades.Count,
89.             result.OpenBreaks.Count);
90.     }
91. }
