215.     private PositionRecord? FindPosition(
216.         TradeRecord trade,
217.         IEnumerable<PositionRecord> candidates,
218.         HashSet<string> usedPositions,
219.         List<string> reasons)
220.     {
221.         List<PositionRecord> available = candidates.Where(candidate => !usedPositions.Contains(candidate.PositionId)).ToList();
222.         if (available.Count == 0)
223.         {
224.             reasons.Add(BreakReasons.MissingPosition);
225.             return null;
226.         }
227. 
228.         List<PositionRecord> sameDate = available.Where(candidate => candidate.SettlementDate == trade.SettlementDate).ToList();
229.         if (sameDate.Count == 0)
230.         {
231.             reasons.Add(BreakReasons.PositionSettlementDateMismatch);
232.             return null;
233.         }
234. 
235.         List<PositionRecord> sameCurrency = sameDate.Where(candidate => Normalize(candidate.Currency) == Normalize(trade.Currency)).ToList();
236.         if (sameCurrency.Count == 0)
237.         {
238.             reasons.Add(BreakReasons.PositionCurrencyMismatch);
239.             return null;
240.         }
241. 
242.         PositionRecord candidatePosition = sameCurrency
243.             .OrderBy(candidate => Math.Abs(candidate.Quantity - trade.Quantity))
244.             .ThenBy(candidate => candidate.PositionId, StringComparer.Ordinal)
245.             .First();
246. 
247.         if (Math.Sign(candidatePosition.Quantity) != Math.Sign(trade.Quantity))
248.         {
249.             reasons.Add(BreakReasons.PositionQuantitySignMismatch);
250.             return null;
251.         }
252. 
253.         if (Math.Abs(candidatePosition.Quantity - trade.Quantity) > _options.PositionQuantityTolerance)
254.         {
255.             reasons.Add(BreakReasons.PositionQuantityOutOfTolerance);
256.             return null;
257.         }
258. 
259.         return candidatePosition;
260.     }
