using TradeReconciliation.Infrastructure;
using TradeReconciliation.Infrastructure.Csv;
using Xunit;

namespace TradeReconciliation.Tests;

/// <summary>Ingestion, publication and containment behaviour of the CSV boundary.</summary>
public sealed class CsvFileGatewayTests
{
    private static readonly CsvFileGateway Gateway = new();

    [Fact]
    public void Header_rows_blank_lines_and_surrounding_whitespace_are_ignored()
    {
        using TempDirectory input = new();
        input.WriteLines(
            "trades.csv",
            "trade_id,account,instrument,quantity,settlement_date,currency,net_amount",
            "",
            "  T-1 , ACC-1 ,IBM.N, 100 ,2025-03-17,USD, 1000 ",
            "   ");

        TradeRecord trade = Assert.Single(Gateway.LoadTrades(input.Path));

        Assert.Equal("T-1", trade.TradeId);
        Assert.Equal("ACC-1", trade.Account);
        Assert.Equal(100m, trade.Quantity);
        Assert.Equal(1000m, trade.NetAmount);
    }

    [Fact]
    public void A_missing_required_input_file_is_reported_as_an_input_error()
    {
        using TempDirectory input = new();

        ReconciliationInputException error = Assert.Throws<ReconciliationInputException>(
            () => Gateway.LoadTrades(input.Path));

        Assert.Contains("trades.csv", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void The_optional_override_file_is_treated_as_empty_when_absent()
    {
        using TempDirectory input = new();

        Assert.Empty(Gateway.LoadOverrides(input.Path));
    }

    [Fact]
    public void A_row_with_the_wrong_column_count_names_the_file_and_line()
    {
        using TempDirectory input = new();
        input.WriteLines(
            "positions.csv",
            "position_id,account,instrument,quantity,settlement_date,currency",
            "P-1,ACC-1,IBM.N,100,2025-03-17");

        ReconciliationInputException error = Assert.Throws<ReconciliationInputException>(
            () => Gateway.LoadPositions(input.Path));

        Assert.Contains("positions.csv", error.Message, StringComparison.Ordinal);
        Assert.Contains("2", error.Message, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("S-1,ACC-1,IBM.N,not-a-number,2025-03-17,USD,1000")]
    [InlineData("S-1,ACC-1,IBM.N,100,17/03/2025,USD,1000")]
    public void Unparseable_numbers_and_dates_are_rejected_rather_than_silently_defaulted(string row)
    {
        using TempDirectory input = new();
        input.WriteLines(
            "settlements.csv",
            "settlement_id,account,instrument,quantity,settlement_date,currency,cash_amount",
            row);

        Assert.Throws<ReconciliationInputException>(() => Gateway.LoadSettlements(input.Path));
    }

    [Fact]
    public void Input_paths_are_confined_to_the_declared_input_directory()
    {
        using TempDirectory input = new();

        Assert.Throws<ReconciliationInputException>(
            () => Gateway.LoadTrades(Path.Combine(input.Path, "..", "..", "elsewhere")));
    }

    [Fact]
    public void Matched_trades_are_written_with_the_frozen_header_and_ordinal_ordering()
    {
        using TempDirectory output = new();

        Gateway.WriteMatchedTrades(output.Path,
        [
            Matched("T-2"),
            Matched("T-1"),
        ]);

        string[] lines = File.ReadAllLines(output.Combine("matched-trades.csv"));
        Assert.Equal(
            "trade_id,status,account,instrument,quantity,settlement_date,currency,position_id,settlement_id,override_note",
            lines[0]);
        Assert.StartsWith("T-1,", lines[1], StringComparison.Ordinal);
        Assert.StartsWith("T-2,", lines[2], StringComparison.Ordinal);
    }

    [Fact]
    public void Quantities_are_published_with_two_decimals_and_dates_as_iso_8601()
    {
        using TempDirectory output = new();

        Gateway.WriteMatchedTrades(output.Path, [Matched("T-1", 1234.5m)]);

        Assert.Contains("1234.50,2025-03-17,", File.ReadAllLines(output.Combine("matched-trades.csv"))[1], StringComparison.Ordinal);
    }

    [Fact]
    public void An_empty_result_still_publishes_a_header_only_file()
    {
        using TempDirectory output = new();

        Gateway.WriteBreakQueue(output.Path, []);

        string[] lines = File.ReadAllLines(output.Combine("break-queue.csv"));
        Assert.Equal("trade_id,account,instrument,quantity,settlement_date,currency,reasons,position_id,settlement_id", Assert.Single(lines));
    }

    [Fact]
    public void The_output_directory_is_created_on_demand()
    {
        using TempDirectory root = new();
        string nested = root.Combine(Path.Combine("nested", "run"));

        Gateway.WriteEndOfDayReport(nested, "report body");

        Assert.True(File.Exists(Path.Combine(nested, "end-of-day-report.txt")));
    }

    [Fact]
    public void Required_output_presence_is_reported_only_when_every_artefact_exists()
    {
        using TempDirectory output = new();

        Assert.False(Gateway.AllRequiredOutputsExist(output.Path));

        Gateway.WriteMatchedTrades(output.Path, []);
        Gateway.WriteBreakQueue(output.Path, []);

        Assert.False(Gateway.AllRequiredOutputsExist(output.Path));

        Gateway.WriteEndOfDayReport(output.Path, "report body");

        Assert.True(Gateway.AllRequiredOutputsExist(output.Path));
    }

    private static MatchedTradeRecord Matched(string tradeId, decimal quantity = 100m) => new()
    {
        TradeId = tradeId,
        Status = MatchStatuses.Matched,
        Account = "ACC-1",
        Instrument = "IBM.N",
        Quantity = quantity,
        SettlementDate = Build.Settle,
        Currency = "USD",
        PositionId = "P-1",
        SettlementId = "S-1",
        OverrideNote = null,
    };
}

using System.Globalization;
using TradeReconciliation.Application;
using TradeReconciliation.Domain;
using TradeReconciliation.Infrastructure;
using Xunit;

namespace TradeReconciliation.Tests;

/// <summary>The audit ledger and the signature that drives idempotent reruns.</summary>
public sealed class RunLedgerAndSignatureTests
{
    private static readonly DateTime BusinessDate = new(2025, 3, 17);

    private static RunLedgerEntry Entry(string signature, int trades = 10, int breaks = 2, int matched = 8) => new()
    {
        BusinessDate = BusinessDate,
        InputSignature = signature,
        TotalTradesRead = trades,
        OpenBreakCount = breaks,
        MatchedCount = matched,
    };

    [Fact]
    public void A_new_ledger_is_created_with_the_frozen_header_on_first_append()
    {
        using TempDirectory output = new();
        RunLedgerStore store = new(output.Combine("run-ledger.csv"));

        store.AppendIfMissing(Entry("abc123"));

        string[] lines = File.ReadAllLines(output.Combine("run-ledger.csv"));
        Assert.Equal("business_date,input_signature,total_trades_read,open_break_count,matched_count", lines[0]);
        Assert.Equal("2025-03-17,abc123,10,2,8", lines[1]);
    }

    [Fact]
    public void Appending_the_same_business_date_and_signature_twice_does_not_duplicate_the_row()
    {
        using TempDirectory output = new();
        RunLedgerStore store = new(output.Combine("run-ledger.csv"));

        store.AppendIfMissing(Entry("abc123"));
        store.AppendIfMissing(Entry("abc123"));

        Assert.Equal(2, File.ReadAllLines(output.Combine("run-ledger.csv")).Length);
        Assert.Single(store.LoadEntries());
    }

    [Fact]
    public void A_different_signature_for_the_same_date_is_appended_as_a_new_run()
    {
        using TempDirectory output = new();
        RunLedgerStore store = new(output.Combine("run-ledger.csv"));

        store.AppendIfMissing(Entry("abc123"));
        store.AppendIfMissing(Entry("def456"));

        Assert.Equal(2, store.LoadEntries().Count);
        Assert.True(store.Exists(BusinessDate, "abc123"));
        Assert.True(store.Exists(BusinessDate, "def456"));
    }

    [Fact]
    public void Existence_is_scoped_to_both_the_business_date_and_the_signature()
    {
        using TempDirectory output = new();
        RunLedgerStore store = new(output.Combine("run-ledger.csv"));
        store.AppendIfMissing(Entry("abc123"));

        Assert.False(store.Exists(BusinessDate.AddDays(1), "abc123"));
        Assert.False(store.Exists(BusinessDate, "other-signature"));
    }

    [Fact]
    public void An_absent_ledger_reports_no_entries_rather_than_failing()
    {
        using TempDirectory output = new();
        RunLedgerStore store = new(output.Combine("run-ledger.csv"));

        Assert.Empty(store.LoadEntries());
        Assert.False(store.Exists(BusinessDate, "abc123"));
    }

    [Fact]
    public void The_input_signature_is_a_stable_lowercase_sha256_digest()
    {
        using TempDirectory input = new();
        input.WriteLines("trades.csv", "trade_id", "T-1");
        InputSignatureCalculator calculator = new();

        string first = calculator.Calculate(BusinessDate, input.Path);
        string second = calculator.Calculate(BusinessDate, input.Path);

        Assert.Equal(first, second);
        Assert.Equal(64, first.Length);
        Assert.Equal(first, first.ToLower(CultureInfo.InvariantCulture));
    }

    [Fact]
    public void The_signature_changes_when_content_the_business_date_or_the_file_set_changes()
    {
        using TempDirectory input = new();
        input.WriteLines("trades.csv", "trade_id", "T-1");
        InputSignatureCalculator calculator = new();
        string baseline = calculator.Calculate(BusinessDate, input.Path);

        Assert.NotEqual(baseline, calculator.Calculate(BusinessDate.AddDays(1), input.Path));

        input.WriteLines("trades.csv", "trade_id", "T-2");
        string afterContentChange = calculator.Calculate(BusinessDate, input.Path);
        Assert.NotEqual(baseline, afterContentChange);

        input.WriteLines("overrides.csv", "trade_id,action,note,approved_by");
        Assert.NotEqual(afterContentChange, calculator.Calculate(BusinessDate, input.Path));
    }

    [Fact]
    public void A_missing_input_directory_is_surfaced_as_an_input_error()
    {
        using TempDirectory root = new();

        Assert.Throws<ReconciliationInputException>(
            () => new InputSignatureCalculator().Calculate(BusinessDate, root.Combine("absent")));
    }

    [Fact]
    public void The_ledger_factory_binds_the_store_to_the_output_directory()
    {
        using TempDirectory output = new();

        Application.Abstractions.IRunLedger ledger = new RunLedgerStoreFactory().Create(output.Path);
        ledger.AppendIfMissing(Entry("abc123"));

        Assert.True(File.Exists(output.Combine("run-ledger.csv")));
    }
}

