using TradeReconciliation.Application;
using TradeReconciliation.Domain;
using Xunit;

namespace TradeReconciliation.Tests;

/// <summary>The operator-facing summary is part of the observable contract, so its shape is pinned.</summary>
public sealed class EndOfDayReportBuilderTests
{
    private static readonly EndOfDayReportBuilder Builder = new();

    private static ReconciliationResult Result(
        IReadOnlyList<BreakRecord>? breaks = null,
        IReadOnlyList<ManualOverrideRecord>? staleOverrides = null) => new()
        {
            MatchedTrades = [],
            OpenBreaks = breaks ?? [],
            StaleOverrides = staleOverrides ?? [],
            TotalTradesRead = 12,
            CanonicalTradeCount = 11,
            DuplicateTradeCount = 1,
            MatchedCount = 7,
            ManualOverrideMatchedCount = 2,
            ManualOverrideSuppressedCount = 1,
        };

    private static BreakRecord Break(string tradeId, string reasons) => new()
    {
        TradeId = tradeId,
        Account = "ACC-1",
        Instrument = "IBM.N",
        Quantity = 100m,
        SettlementDate = Build.Settle,
        Currency = "USD",
        Reasons = reasons,
        PositionId = null,
        SettlementId = null,
        CanManualOverride = false,
    };

    [Fact]
    public void The_report_opens_with_the_expected_title_and_business_date()
    {
        string report = Builder.BuildReport(new DateTime(2025, 3, 17), Result());

        string[] lines = report.Split(Environment.NewLine);
        Assert.Equal("Legacy Trade Reconciliation - End Of Day Report", lines[0]);
        Assert.Equal("Business Date: 2025-03-17", lines[1]);
    }

    [Fact]
    public void Every_headline_total_is_rendered()
    {
        string report = Builder.BuildReport(Build.Settle, Result());

        Assert.Contains("Trades Read: 12", report, StringComparison.Ordinal);
        Assert.Contains("Canonical Trades: 11", report, StringComparison.Ordinal);
        Assert.Contains("Matched: 7", report, StringComparison.Ordinal);
        Assert.Contains("Manual Override Matched: 2", report, StringComparison.Ordinal);
        Assert.Contains("Manual Override Suppressed: 1", report, StringComparison.Ordinal);
        Assert.Contains("Open Breaks: 0", report, StringComparison.Ordinal);
        Assert.Contains("Duplicate Trades: 1", report, StringComparison.Ordinal);
        Assert.Contains("Stale Overrides: 0", report, StringComparison.Ordinal);
    }

    [Fact]
    public void A_clean_day_renders_None_under_the_break_reason_heading()
    {
        string report = Builder.BuildReport(Build.Settle, Result());

        Assert.Contains("Open Break Reasons" + Environment.NewLine + "------------------" + Environment.NewLine + "None", report, StringComparison.Ordinal);
    }

    [Fact]
    public void Pipe_separated_reasons_are_counted_individually_and_sorted_ordinally()
    {
        string report = Builder.BuildReport(Build.Settle, Result(
        [
            Break("T-1", BreakReasons.MissingPosition + "|" + BreakReasons.MissingSettlement),
            Break("T-2", BreakReasons.MissingPosition),
        ]));

        Assert.Contains(BreakReasons.MissingPosition + ": 2", report, StringComparison.Ordinal);
        Assert.Contains(BreakReasons.MissingSettlement + ": 1", report, StringComparison.Ordinal);
        Assert.True(
            report.IndexOf(BreakReasons.MissingPosition + ": 2", StringComparison.Ordinal) <
            report.IndexOf(BreakReasons.MissingSettlement + ": 1", StringComparison.Ordinal));
    }

    [Fact]
    public void The_stale_override_section_appears_only_when_instructions_were_discarded()
    {
        Assert.DoesNotContain("Stale Overrides" + Environment.NewLine + "---------------", Builder.BuildReport(Build.Settle, Result()), StringComparison.Ordinal);

        string report = Builder.BuildReport(Build.Settle, Result(
            staleOverrides: [Build.Override("T-9", "ForceMatch", "note", "ops-manager")]));

        Assert.Contains("Stale Overrides" + Environment.NewLine + "---------------", report, StringComparison.Ordinal);
        Assert.Contains("T-9: ForceMatch (ops-manager)", report, StringComparison.Ordinal);
    }

    [Fact]
    public void The_report_ends_with_exactly_one_trailing_newline()
    {
        string report = Builder.BuildReport(Build.Settle, Result());

        Assert.EndsWith(Environment.NewLine, report, StringComparison.Ordinal);
        Assert.DoesNotEndWith(Environment.NewLine + Environment.NewLine, report, StringComparison.Ordinal);
    }
}

using TradeReconciliation.Cli;
using Xunit;

namespace TradeReconciliation.Tests;

/// <summary>Argument handling, exit codes and the operator-facing console text.</summary>
public sealed class BatchHostTests
{
    private static (int ExitCode, string Output, string Error) Run(params string[] args)
    {
        using StringWriter output = new();
        using StringWriter error = new();
        int exitCode = BatchHost.Run(args, output, error);
        return (exitCode, output.ToString(), error.ToString());
    }

    [Fact]
    public void The_three_argument_form_reconciles_and_reports_success()
    {
        using TempDirectory output = new();
        string input = Path.Combine(AppContext.BaseDirectory, "Fixtures", "baseline", "input");

        (int exitCode, string standardOutput, string standardError) = Run("2025-03-17", input, output.Path);

        Assert.Equal(ExitCodes.Success, exitCode);
        Assert.Contains("Processed", standardOutput, StringComparison.Ordinal);
        Assert.Contains("open breaks.", standardOutput, StringComparison.Ordinal);
        Assert.Empty(standardError);
    }

    [Fact]
    public void An_exact_rerun_reports_that_existing_outputs_were_retained()
    {
        using TempDirectory output = new();
        string input = Path.Combine(AppContext.BaseDirectory, "Fixtures", "baseline", "input");

        Run("2025-03-17", input, output.Path);
        (int exitCode, string standardOutput, _) = Run("2025-03-17", input, output.Path);

        Assert.Equal(ExitCodes.Success, exitCode);
        Assert.Equal(
            "Exact rerun detected for 2025-03-17. Existing outputs were retained.",
            standardOutput.Trim());
    }

    [Theory]
    [InlineData("--help")]
    [InlineData("-h")]
    [InlineData("-?")]
    [InlineData("/?")]
    public void Help_switches_print_usage_and_succeed(string switchText)
    {
        (int exitCode, string standardOutput, _) = Run(switchText);

        Assert.Equal(ExitCodes.Success, exitCode);
        Assert.Contains("Usage:", standardOutput, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(new[] { "2025-03-17" })]
    [InlineData(new[] { "2025-03-17", "input" })]
    [InlineData(new[] { "2025-03-17", "input", "output", "extra" })]
    public void An_unsupported_argument_count_is_a_usage_error(string[] args)
    {
        (int exitCode, _, string standardError) = Run(args);

        Assert.Equal(ExitCodes.UsageError, exitCode);
        Assert.Contains("Usage:", standardError, StringComparison.Ordinal);
    }

    [Fact]
    public void A_malformed_business_date_is_a_usage_error_naming_the_expected_format()
    {
        (int exitCode, _, string standardError) = Run("17-03-2025", "input", "output");

        Assert.Equal(ExitCodes.UsageError, exitCode);
        Assert.Contains("yyyy-MM-dd", standardError, StringComparison.Ordinal);
    }

    [Fact]
    public void An_empty_directory_argument_is_rejected_before_any_file_access()
    {
        (int exitCode, _, string standardError) = Run("2025-03-17", "   ", "output");

        Assert.Equal(ExitCodes.UsageError, exitCode);
        Assert.Contains("must not be empty", standardError, StringComparison.Ordinal);
    }

    [Fact]
    public void A_missing_input_directory_is_an_input_error_rather_than_a_crash()
    {
        using TempDirectory root = new();

        (int exitCode, _, string standardError) = Run("2025-03-17", root.Combine("absent"), root.Combine("out"));

        Assert.Equal(ExitCodes.InputError, exitCode);
        Assert.NotEmpty(standardError);
    }

    [Fact]
    public void Exit_codes_are_distinct_so_schedulers_can_route_failures()
    {
        Assert.Equal(0, ExitCodes.Success);
        Assert.NotEqual(ExitCodes.Success, ExitCodes.UsageError);
        Assert.NotEqual(ExitCodes.UsageError, ExitCodes.InputError);
        Assert.NotEqual(ExitCodes.Success, ExitCodes.UnexpectedFailure);
    }
}

